promql:
# Number of processes currently blocked waiting for I/O to complete on nodes hosting the tsdb-mysql service
node_procs_blocked{service="tsdb-mysql"}

# Ratio of blocked processes to runnable processes on the same nodes
(
  node_procs_blocked{service="tsdb-mysql"}
  /
  node_procs_running{service="tsdb-mysql"}
)

histogram_quantile(0.95, 
  sum by (le) (
    increase(traces_spanmetrics_latency_bucket{internal="false"}[1h])
  )
) 
  and on ()
avg_over_time(
  (
    sum by (le) (
      increase(traces_spanmetrics_latency_bucket{internal="false"}[1h])
    ) / sum by (le) (
      increase(traces_spanmetrics_latency_bucket_count{internal="false"}[1h])
    )
  )[1h:1m]
) >= 0.01

(
  label_replace(
    histogram_quantile(0.99, sum(rate(traces_service_graph_request_client_seconds_bucket{service="ts-route-service"}[5m])) by (le)),
    "quantile", "99th", "", ""
  ),
  label_replace(
    histogram_quantile(0.95, sum(rate(traces_service_graph_request_client_seconds_bucket{service="ts-route-service"}[5m])) by (le)),
    "quantile", "95th", "", ""
  )
)

# Current number of TCP orphan sockets on nodes running the auth service
node_sockstat_TCP_orphan{service="auth"}

# Ratio of current number to that from one week ago
(
  node_sockstat_TCP_orphan{service="auth"}
  /
  node_sockstat_TCP_orphan{service="auth"} offset 1w
)

histogram_quantile(
  0.8,
  sum by (le) (
    rate(
      traces_service_graph_request_client_seconds_bucket{
        source_service="auth",
        destination_service="verification_code"
      }[5m]
    )
  )
)
